import{_ as a,c as t,a2 as r,o as s}from"./chunks/framework.CoXjB5sU.js";const u=JSON.parse('{"title":"An error page appears after login","description":"","frontmatter":{"prev":{"text":"Errors FAQs","link":"/doc/faqs/error"},"next":false},"headers":[],"relativePath":"doc/faqs/errors/user-email-required.md","filePath":"doc/faqs/errors/user-email-required.md"}'),o={name:"doc/faqs/errors/user-email-required.md"};function i(n,e,l,h,p,d){return s(),t("div",null,e[0]||(e[0]=[r('<h1 id="an-error-page-appears-after-login" tabindex="-1">An error page appears after login <a class="header-anchor" href="#an-error-page-appears-after-login" aria-label="Permalink to &quot;An error page appears after login&quot;">​</a></h1><p>This error usually appears on the first login right after installing ioChem-BD: instead of the module, the browser shows an error page about the login (for example, that the user email is required).</p><h2 id="cause" tabindex="-1">Cause <a class="header-anchor" href="#cause" aria-label="Permalink to &quot;Cause&quot;">​</a></h2><p>The modules check the login with CAS through the public hostname. If the server can&#39;t resolve its own hostname, they can&#39;t reach CAS and get no user information after the login. The installer warns about it (<em>does not resolve: add it to /etc/hosts</em>), but the warning doesn&#39;t stop the installation.</p><h2 id="steps-to-fix-it" tabindex="-1">Steps to fix it <a class="header-anchor" href="#steps-to-fix-it" aria-label="Permalink to &quot;Steps to fix it&quot;">​</a></h2><p>As root, add a line to <em>/etc/hosts</em> that maps the loopback IP (127.0.0.1) to the <a href="./../../guides/installation/required-steps.html#web-service-and-https-certificate">hostname set during the installation</a>. For example, for <em>test.iochem-bd.org</em>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">127.0.0.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.iochem-bd.org</span></span></code></pre></div><p>Then reload the page or log in again.</p>',8)]))}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
